#!/usr/bin/env python3
"""Adds Dost permissions/settings to the Android & iOS projects generated by `flutter create`.

Usage (inside the app/ folder):
    flutter create --org tm.dost --project-name dost --platforms android,ios .
    python3 tool/setup_platforms.py            # production (HTTPS only)
    python3 tool/setup_platforms.py --allow-http   # testing against http://IP:8080
"""
import pathlib
import re
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
ALLOW_HTTP = "--allow-http" in sys.argv


def patch_android():
    man = ROOT / "android/app/src/main/AndroidManifest.xml"
    s = man.read_text()
    perms = [
        "android.permission.INTERNET",
        "android.permission.RECORD_AUDIO",
        "android.permission.READ_CONTACTS",
        "android.permission.VIBRATE",
    ]
    for p in perms:
        if p not in s:
            s = s.replace("<application", f'<uses-permission android:name="{p}"/>\n    <application', 1)
    s = re.sub(r'android:label="[^"]*"', 'android:label="Dost"', s, count=1)
    if ALLOW_HTTP and "usesCleartextTraffic" not in s:
        s = s.replace("<application", '<application android:usesCleartextTraffic="true"', 1)
    man.write_text(s)

    for name in ("build.gradle.kts", "build.gradle"):
        g = ROOT / "android/app" / name
        if g.exists():
            t = g.read_text()
            t = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 24", t)
            t = re.sub(r"minSdkVersion\s+flutter\.minSdkVersion", "minSdkVersion 24", t)
            g.write_text(t)
    print("android: ok")


def plist_set(s, key, value_xml):
    if f"<key>{key}</key>" in s:
        return s
    return s.replace("<dict>", f"<dict>\n\t<key>{key}</key>\n\t{value_xml}", 1)


def patch_ios():
    pl = ROOT / "ios/Runner/Info.plist"
    s = pl.read_text()
    s = plist_set(s, "NSMicrophoneUsageDescription",
                  "<string>Sesli habar ýazmak üçin / Для записи голосовых сообщений</string>")
    s = plist_set(s, "NSPhotoLibraryUsageDescription",
                  "<string>Surat ugratmak üçin / Чтобы отправлять фото</string>")
    s = plist_set(s, "NSCameraUsageDescription",
                  "<string>Surat düşürip ugratmak üçin / Чтобы снимать и отправлять фото</string>")
    s = plist_set(s, "NSContactsUsageDescription",
                  "<string>Dost-daky dostlaryňyzy tapmak üçin / Чтобы найти друзей в Dost</string>")
    s = re.sub(r"(<key>CFBundleDisplayName</key>\s*<string>)[^<]*(</string>)", r"\1Dost\2", s)
    if ALLOW_HTTP:
        s = plist_set(s, "NSAppTransportSecurity",
                      "<dict>\n\t\t<key>NSAllowsArbitraryLoads</key>\n\t\t<true/>\n\t</dict>")
    pl.write_text(s)

    pod = ROOT / "ios/Podfile"
    if pod.exists():
        t = pod.read_text()
        t = re.sub(r"^#?\s*platform :ios.*$", "platform :ios, '13.0'", t, flags=re.M)
        pod.write_text(t)
    print("ios: ok")


if __name__ == "__main__":
    if (ROOT / "android").exists():
        patch_android()
    if (ROOT / "ios").exists():
        patch_ios()
